package leetcode.medium;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

public class OnlineStockSpanTest {

    private List<Integer> list = new ArrayList<>();

    @Test
    public void next_AddsPriceToList() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(10);
        assertEquals(1, list.size());
    }

    @Test
    public void next_PriceIsGreaterOrEqualThanLastPrice() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(10);
        stockSpan.next(8);
        assertTrue(stockSpan.list.get(0) == 9);
    }

    @Test
    public void next_PriceIsLessThanFirstPrice() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(5);
        stockSpan.next(4);
        assertEquals(2, list.get(0));
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpans() {
        int[] prices = {100, 80, 75, 70, 60};
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.calculateSpans(prices);
        assertArrayEquals(new int[]{1, 2, 3, 4}, stockSpan.list.toArray());
    }

    @Test
    public void calculateSpans_CalculateSpansForEmptyPrices() {
        int[] prices = {};
        int[] expectedSpans = {0};
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.calculateSpans(prices);
        assertArrayEquals(expectedSpans, stockSpan.list.toArray());
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForNonIncreasingPrices() {
        int[] prices = {100, 90, 80, 70};
        int[] expectedSpans = new int[]{1, 3, 5, 6};
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.calculateSpans(prices);
        assertArrayEquals(expectedSpans, stockSpan.list.toArray());
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForNonDecreasingPrices() {
        int[] prices = {100, 110, 90, 80};
        int[] expectedSpans = new int[]{2, 1, 3, 4};
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.calculateSpans(prices);
        assertArrayEquals(expectedSpans, stockSpan.list.toArray());
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForIncreasingPrices() {
        int[] prices = {100, 80, 70, 60};
        int[] expectedSpans = new int[]{1, 2, 3, 4};
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.calculateSpans(prices);
        assertArrayEquals(expectedSpans, stockSpan.list.toArray());
    }

    @Test
    public void next_DoesNotIncreaseIndex() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        stockSpan.next(10);
        assertEquals(0, stockSpan.list.get(1));
    }
}
